class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n
        self.size = [1] * n

    def find(self, u):
        if self.parent[u] != u:
            self.parent[u] = self.find(self.parent[u])
        return self.parent[u]

    def union(self, u, v):
        root_u = self.find(u)
        root_v = self.find(v)
        if root_u != root_v:
            if self.rank[root_u] > self.rank[root_v]:
                self.parent[root_v] = root_u
                self.size[root_u] += self.size[root_v]
            else:
                self.parent[root_u] = root_v
                self.size[root_v] += self.size[root_u]
                if self.rank[root_u] == self.rank[root_v]:
                    self.rank[root_v] += 1
            return True
        return False

    def get_size(self, u):
        return self.size[self.find(u)]

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    index = 0
    n = int(data[index])
    m = int(data[index + 1])
    index += 2

    edges = []
    for i in range(m):
        ai = int(data[index]) - 1
        bi = int(data[index + 1]) - 1
        li = int(data[index + 2])
        edges.append((li, ai, bi, i + 1))
        index += 3

    edges.sort()
    uf = UnionFind(n)
    paved_edges = []
    max_length = -1

    for li, ai, bi, idx in edges:
        if uf.union(ai, bi):
            paved_edges.append((li, ai, bi, idx))
            uf.get_size(ai)
            odd_count = 0
            for j in range(n):
                if uf.get_size(j) % 2 == 1:
                    odd_count += 1
            if odd_count <= 1:
                max_length = li
            else:
                max_length = -1
                break

    for li, ai, bi, idx in paved_edges:
        print(max_length)

if __name__ == "__main__":
    main()
